Given transaction records, find the transaction with the highest amount.

Input:
transactions = [
    {"id": 101, "amount": 500},
    {"id": 102, "amount": 1200},
    {"id": 103, "amount": 800}
]

Expected Output:
{"id": 102, "amount": 1200}

questions.referenceAnswer:
def highest_transaction(transactions):
    highest = transactions[0]
    for transaction in transactions:
        if transaction["amount"] > highest["amount"]:
            highest = transaction
    return highest

print(highest_transaction(transactions))

def find_missing_records(source, destination):
    destination_ids = set()
    for record in destination:
        destination_ids.add(record["id"])
    result = []
    for record in source:
        if record["id"] not in destination_ids:
            result.append(record["id"])
    return result

print(find_missing_records(source, destination))

def find_palindromes(words):
    result = []
    for word in words:
        if word == word[::-1]:
            result.append(word)
    return result

print(find_palindromes(words))

def difference(list1, list2):
    result = []
    for item in list1:
        if item not in list2:
            result.append(item)
    return result

print(difference(list1, list2))

def longest_word(words):
    longest = words[0]
    for word in words:
        if len(word) > len(longest):
            longest = word
    return longest

print(longest_word(words))

def split_numbers(numbers):
    positive = []
    negative = []
    for num in numbers:
        if num > 0:
            positive.append(num)
        elif num < 0:
            negative.append(num)
    return positive, negative

positive, negative = split_numbers(numbers)
print("Positive:", positive)
print("Negative:", negative)

